package net.officefloor.hq.app.audit;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class AuditViewController {

    private final AuditViewService service;

    public AuditViewController(AuditViewService service) {
        this.service = service;
    }

    /** The sheet's audit lines, newest first; with a name only those about that person, then its descendants' ones. */
    @GetMapping("/audit")
    public List<String> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestParam(name = "name", required = false, defaultValue = "") @Size(max = 200) String name) {
        return service.lines(sheetId, name);
    }

    /** A claim's timeline: the audit lines about it, newest first. */
    @GetMapping("/claims/{id}/timeline")
    public List<String> claimTimeline(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.claimLines(sheetId, id);
    }
}
package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNotFoundException;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Reads back the audit file for a sheet: it is not a second record, only a view of what the file
 * holds.
 */
@Service
public class AuditViewService {

    private final Audit audit;
    private final PersonRepository people;
    private final SheetParentRepository parents;
    private final ClaimRepository claims;

    public AuditViewService(Audit audit, PersonRepository people, SheetParentRepository parents,
            ClaimRepository claims) {
        this.audit = audit;
        this.people = people;
        this.parents = parents;
        this.claims = claims;
    }

    /**
     * A claim's timeline: the sheet's audit lines about it exactly as the file holds them, newest first.
     * For a claim with a number those carrying number=<its number>; for one without, those without a
     * number that name its person, amount and date together.
     */
    @Transactional(readOnly = true)
    public List<String> claimLines(String sheetId, Long claimId) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Pattern numbered = Pattern.compile(" number=[^ ]*(?= [^ =]+=|$)");
        Pattern about;
        if (claim.getNumber() != null) {
            about = Pattern.compile(" number=" + Pattern.quote(claim.getNumber()) + "(?= [^ =]+=|$)");
        } else {
            String name = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse(null);
            if (name == null) return List.of();
            about = Pattern.compile(" person=" + Pattern.quote(name)
                    + " amount=" + Pattern.quote(claim.getAmount().setScale(2).toPlainString())
                    + " date=" + Pattern.quote(claim.getDate().toString()) + "(?= [^ =]+=|$)");
        }
        List<String> out = linesOf(audit.lines(), sheetId, about);
        if (claim.getNumber() == null) out.removeIf(line -> numbered.matcher(line).find());
        return out;
    }

    /**
     * The sheet's audit lines exactly as the file holds them, newest first. With a name (blank: none)
     * only those carrying name=<the name> or person=<the name>, the name compared without surrounding
     * spaces and ignoring case, followed by the matching lines of the sheet's descendants (each
     * sheet's newest first, the sheets in order of id); when the name, or an alias, is of a person transferred here, they are
     * followed by the lines about them from the sheet they came from, up to the one of their transfer
     * here, newest first.
     */
    @Transactional(readOnly = true)
    public List<String> lines(String sheetId, String name) {
        String wanted = name == null ? "" : name.strip();
        Pattern about = wanted.isEmpty() ? null
                : Pattern.compile(" (?:name|person)=" + Pattern.quote(wanted) + "(?= [^ =]+=|$)",
                        Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
        List<String> all = audit.lines();
        List<String> out = linesOf(all, sheetId, about);
        if (about == null) return out;
        List<String> descendants = new ArrayList<>(parents.descendantsOf(sheetId));
        Collections.sort(descendants);
        for (String descendant : descendants) out.addAll(linesOf(all, descendant, about));
        String origin = people.findByNameOrAlias(sheetId, wanted).map(Person::getTransferredFrom).orElse(null);
        if (origin == null || origin.equals(sheetId)) return out;
        List<String> theirs = linesOf(all, origin, about);
        String transfer = "PERSON_TRANSFERRED sheet=" + origin + " ";
        String toHere = " to=" + sheetId;
        for (int i = 0; i < theirs.size(); i++) {
            String line = theirs.get(i);
            if (line.startsWith(transfer) && (line.endsWith(toHere) || line.contains(toHere + " "))) {
                out.addAll(theirs.subList(i, theirs.size()));
                break;
            }
        }
        return out;
    }

    /** The sheet's lines, newest first; with a pattern only those it finds. */
    private static List<String> linesOf(List<String> all, String sheetId, Pattern about) {
        String sheetField = "sheet=" + sheetId;
        List<String> out = new ArrayList<>();
        for (String line : all) {
            String[] fields = line.split(" ", 3);
            if (fields.length < 2 || !fields[1].equals(sheetField)) continue;
            if (about != null && !about.matcher(line).find()) continue;
            out.add(line);
        }
        Collections.reverse(out);
        return out;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The sheet's audit lines as the file holds them, newest first; a name in the filter shows only
// the lines about that person (name=… or person=…, compared as names are).
@Component({
  selector: 'app-audit-view',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="audit-heading">
      <h2 id="audit-heading">Audit</h2>
      <form [formGroup]="form" (ngSubmit)="show()" aria-label="Show the audit">
        <label for="audit-filter">Person</label>
        <input id="audit-filter" data-testid="audit-filter" formControlName="name" />
        <button type="submit" data-testid="audit-show">Show</button>
        @if (error()) {
          <p role="alert" class="error" data-testid="audit-error">{{ error() }}</p>
        }
      </form>
      <ol aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditView {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal('');
  protected readonly form = new FormGroup({ name: new FormControl('', { nonNullable: true }) });
  /** Counts the presses of show, so only the answer to the latest is shown. */
  private request = 0;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      this.request++;
      this.lines.set([]);
      this.error.set('');
    });
  }

  protected async show(): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const request = ++this.request;
    this.lines.set([]);
    this.error.set('');
    try {
      const list = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, {
          headers: { 'X-User': this.session.user() ?? '' },
          params: { name: this.form.controls.name.value },
        }),
      );
      if (request === this.request) this.lines.set(list);
    } catch {
      if (request === this.request) this.error.set('Could not read the audit.');
    }
  }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 *
 * A change made by a user acting as a steward through a delegation has {@code for=<the steward who
 * delegated>} at the end of each of its lines, but for those that only report figures.
 */
@Service
public class Audit {

    /** The events that only report figures: never marked as made for a delegator. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final ObjectProvider<SettingService> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingService> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String line) {
        String entry = line + forDelegator(line);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /**
     * " for=<steward>" when the line, of the form {@code EVENT sheet=<id> by=<user> ...}, is of a change
     * its user makes acting for a steward who delegated to them; else "".
     */
    private String forDelegator(String line) {
        String[] fields = line.split(" ", 4);
        if (fields.length < 3 || FIGURES_ONLY.contains(fields[0])) return "";
        if (!fields[1].startsWith("sheet=") || !fields[2].startsWith("by=")) return "";
        String sheetId = fields[1].substring("sheet=".length());
        String user = fields[2].substring("by=".length());
        if (sheetId.isEmpty() || user.isEmpty()) return "";
        String delegator = settings.getObject().actingFor(sheetId, user);
        return delegator == null ? "" : " for=" + delegator;
    }

    /** Every record the file holds, oldest first; none when there is no file yet. */
    public synchronized List<String> lines() {
        try {
            return Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
